import React, { useState, useEffect } from 'react';
import { getLatestReadings, getSensorStats, getRecentAlerts, getAlertStats } from '../api/api';

// This makes the time look okay
function formatTime(t) {
  if (t == "" || t == null) {
    return 'N/A';
  }
  let d = new Date(t);
  return d.toLocaleString();
}

function Dashboard() {
  // All my state variables
  const [latestReadings, setLatestReadings] = useState([]);
  const [sensorStats, setSensorStats] = useState(null);
  const [recentAlerts, setRecentAlerts] = useState([]);
  const [alertStats, setAlertStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // This function gets all the data one by one
  async function loadData() {
    setLoading(true);
    setError(null);

    try {
      // Get the readings
      let r = await getLatestReadings();
      setLatestReadings(r.data);

      // Get the stats
      let s = await getSensorStats();
      setSensorStats(s);

      // Get the alerts (only 5)
      let a = await getRecentAlerts(5);
      setRecentAlerts(a.data);

      // Get the alert stats
      let as = await getAlertStats();
      setAlertStats(as);

      setLoading(false);
    } catch (err) {
      setError('Something went wrong. Please check if the backend is on.');
      setLoading(false);
    }
  }

  useEffect(() => {
    loadData();

    // Refresh every 30 seconds
    const myInterval = setInterval(function() {
      loadData();
    }, 30000);

    return () => {
      clearInterval(myInterval);
    };
  }, []);

  if (loading === true) {
    return <div>Loading... Please wait...</div>;
  }

  if (error !== null) {
    return (
      <div>
        <p>{error}</p>
        <button onClick={loadData}>Try Again</button>
      </div>
    );
  }

  return (
    <div>
      <div style={{ display: 'flex' }}>
        <h1>Dashboard Overview</h1>
        <button onClick={loadData} style={{ marginLeft: '20px' }}>Refresh</button>
      </div>

      {/* Statistics section */}
      <div style={{ display: 'flex', gap: '10px' }}>
        <div style={{ border: '1px solid blue', padding: '10px' }}>
          <p>Total Readings</p>
          <h2>{sensorStats.total_readings}</h2>
        </div>
        <div style={{ border: '1px solid green', padding: '10px' }}>
          <p>Active Devices</p>
          <h2>{sensorStats.total_topics}</h2>
        </div>
        <div style={{ border: '1px solid red', padding: '10px' }}>
          <p>Total Alerts</p>
          <h2>{alertStats.total_alerts}</h2>
        </div>
      </div>

      {/* Sensor List */}
      <h3>Latest Sensor Readings</h3>
      <div style={{ display: 'flex', flexWrap: 'wrap' }}>
        {latestReadings.map((item) => (
          <div key={item.id} style={{ border: '1px solid gray', margin: '5px', padding: '10px' }}>
            <p><b>{item.topic}</b></p>
            <p>Time: {formatTime(item.received_at)}</p>

            {item.temperature !== null && (
               <p>Temp: {item.temperature} °C</p>
            )}
            {item.humidity !== null && (
               <p>Humidity: {item.humidity} %</p>
            )}
            {item.voltage !== null && (
               <p>Voltage: {item.voltage} V</p>
            )}
            {item.current !== null && (
               <p>Current: {item.current} A</p>
            )}
          </div>
        ))}
      </div>

      {/* Recent Alerts List */}
      <h3>Recent Alerts</h3>
      {recentAlerts.length === 0 ? (
        <p>No alerts!</p>
      ) : (
        recentAlerts.map((alert) => (
          <div key={alert.id} style={{ backgroundColor: '#f9f9f9', padding: '10px', borderBottom: '1px solid #ccc' }}>
            <p><b>Location:</b> {alert.topic}</p>
            <p><b>Type:</b> {alert.severity}</p>
            <p><b>Problems:</b> {alert.violated_keys.join(', ')}</p>
          </div>
        ))
      )}
    </div>
  );
}

export default Dashboard;
